<?php if($section==='billing'):?><div class="card"><h3>Extra AI capacity, when you need it.</h3><p>Your credit balance: <strong><?=(int)value('SELECT credits FROM ai_credit_balances WHERE user_id=?',[$user['id']])?></strong>. Purchased credits are used after the monthly plan allowance.</p><form data-extra-checkout><input type="hidden" name="purpose" value="ai_credits"><button class="button">Buy <?=(int)setting('ai_pack_credits',100)?> credits · <?=money((int)setting('ai_pack_price',49900))?></button></form><p class="small">An AI provider must be configured to use credits.</p></div><?php elseif($section==='human-services'):?><div class="card"><h3>Service quotes</h3><p class="small">Your budget is a request. Only an administrator’s confirmed quote determines the checkout amount.</p><?php foreach(rows('SELECT r.*,(SELECT status FROM payments p WHERE p.service_request_id=r.id ORDER BY p.id DESC LIMIT 1) AS payment_status FROM human_service_requests r WHERE r.website_id=? AND r.user_id=? AND r.quoted_amount IS NOT NULL ORDER BY r.id DESC',[$wid,$user['id']]) as $quote):?><div class="issue"><h3><?=e($quote['service'])?></h3><p><?=money((int)$quote['quoted_amount'])?> · <?=e($quote['payment_status']??'Awaiting payment')?></p><?php if($quote['payment_status']!=='paid'):?><form data-extra-checkout><input type="hidden" name="purpose" value="service"><input type="hidden" name="service_request_id" value="<?=$quote['id']?>"><button class="button small-button">Accept quote & pay</button></form><?php endif;?></div><?php endforeach;?></div><script src="https://checkout.razorpay.com/v1/checkout.js" defer></script><?php endif;?><script src="<?=url('/assets/js/extras.js')?>" defer></script>
